// =====================================================
// FORMATO DE MONEDA MXN - Pesos Mexicanos
// =====================================================
const formatMXN = (amount, decimals = 2) => {
  if (amount === null || amount === undefined || isNaN(amount)) return '$0.00 MXN';
  return new Intl.NumberFormat('es-MX', {
    style: 'currency',
    currency: 'MXN',
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals
  }).format(amount);
};

const formatMXNShort = (amount) => {
  if (amount === null || amount === undefined || isNaN(amount)) return '$0';
  if (amount >= 1000000) {
    return `$${(amount / 1000000).toFixed(1)}M MXN`;
  } else if (amount >= 1000) {
    return `$${(amount / 1000).toFixed(1)}K MXN`;
  }
  return formatMXN(amount, 0);
};

const formatPercentage = (value, decimals = 1) => {
  if (value === null || value === undefined || isNaN(value)) return '0%';
  return `${parseFloat(value).toFixed(decimals)}%`;
};

