// =====================================================
// IndexedDB para almacenamiento de documentos grandes
// Soporta hasta 2GB por archivo - ideal para estados financieros y expedientes judiciales
// =====================================================
const DB_NAME = 'VerticeDocumentsDB';
const DB_VERSION = 1;
const STORE_NAME = 'documents';

const openDocumentsDB = () => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        store.createIndex('agentId', 'agentId', { unique: false });
        store.createIndex('uploadedAt', 'uploadedAt', { unique: false });
      }
    };
  });
};

const saveDocumentToDB = async (doc) => {
  try {
    const db = await openDocumentsDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([STORE_NAME], 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(doc);

      request.onsuccess = () => resolve(doc.id);
      request.onerror = () => reject(request.error);

      transaction.oncomplete = () => db.close();
    });
  } catch (error) {
    console.error('Error saving document to IndexedDB:', error);
    throw error;
  }
};

const getDocumentFromDB = async (docId) => {
  try {
    const db = await openDocumentsDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([STORE_NAME], 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.get(docId);

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);

      transaction.oncomplete = () => db.close();
    });
  } catch (error) {
    console.error('Error getting document from IndexedDB:', error);
    return null;
  }
};

const getDocumentsByAgentFromDB = async (agentId) => {
  try {
    const db = await openDocumentsDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([STORE_NAME], 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const index = store.index('agentId');
      const request = index.getAll(agentId);

      request.onsuccess = () => resolve(request.result || []);
      request.onerror = () => reject(request.error);

      transaction.oncomplete = () => db.close();
    });
  } catch (error) {
    console.error('Error getting documents by agent from IndexedDB:', error);
    return [];
  }
};

const getAllDocumentsFromDB = async () => {
  try {
    const db = await openDocumentsDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([STORE_NAME], 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = () => {
        const docs = request.result || [];
        // Agrupar por agentId
        const grouped = {};
        docs.forEach(doc => {
          if (!grouped[doc.agentId]) grouped[doc.agentId] = [];
          grouped[doc.agentId].push(doc);
        });
        resolve(grouped);
      };
      request.onerror = () => reject(request.error);

      transaction.oncomplete = () => db.close();
    });
  } catch (error) {
    console.error('Error getting all documents from IndexedDB:', error);
    return {};
  }
};

const deleteDocumentFromDB = async (docId) => {
  try {
    const db = await openDocumentsDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction([STORE_NAME], 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.delete(docId);

      request.onsuccess = () => resolve(true);
      request.onerror = () => reject(request.error);

      transaction.oncomplete = () => db.close();
    });
  } catch (error) {
    console.error('Error deleting document from IndexedDB:', error);
    return false;
  }
};

