const getExchangeRate = async (apiUrl = 'http://localhost:3001') => {
  try {
    const now = Date.now();
    if (exchangeRateCache.rate && exchangeRateCache.timestamp &&
      (now - exchangeRateCache.timestamp) < exchangeRateCache.cacheDuration) {
      return exchangeRateCache.rate;
  }

  const response = await fetch(`${apiUrl}/api/exchange-rate`);
  const data = await response.json();

  if (data.success) {
    exchangeRateCache.rate = data.rate;
    exchangeRateCache.timestamp = now;
    return data.rate;
  }
    return 17.50; // Fallback
  } catch (error) {
    console.error('Error getting exchange rate:', error);
    return 17.50; // Fallback
  }
};

const convertUSDtoMXN = async (amountUSD, apiUrl = 'http://localhost:3001') => {
  const rate = await getExchangeRate(apiUrl);
  return amountUSD * rate;
};

// Chart generation helper for PDF/Word
const generateChartCanvas = (chartData, width = 400, height = 250) => {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  const { tipo, titulo, datos } = chartData;
  const { labels, valores, colores } = datos;

  // Background
  ctx.fillStyle = '#1F2937';
  ctx.fillRect(0, 0, width, height);

  // Title
  ctx.fillStyle = '#FFFFFF';
  ctx.font = 'bold 14px Arial';
  ctx.textAlign = 'center';
  ctx.fillText(titulo, width / 2, 25);

  const chartArea = { x: 50, y: 45, w: width - 100, h: height - 90 };
  const total = valores.reduce((a, b) => a + b, 0);

  if (tipo === 'pie' || tipo === 'doughnut') {
    const centerX = width / 2;
    const centerY = chartArea.y + chartArea.h / 2;
    const radius = Math.min(chartArea.w, chartArea.h) / 2 - 10;
    let startAngle = -Math.PI / 2;

    valores.forEach((val, i) => {
      const sliceAngle = (val / total) * 2 * Math.PI;
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
      ctx.closePath();
      ctx.fillStyle = colores[i] || `hsl(${i * 60}, 70%, 50%)`;
      ctx.fill();
      ctx.strokeStyle = '#1F2937';
      ctx.lineWidth = 2;
      ctx.stroke();
      startAngle += sliceAngle;
    });

    if (tipo === 'doughnut') {
      ctx.beginPath();
      ctx.arc(centerX, centerY, radius * 0.5, 0, 2 * Math.PI);
      ctx.fillStyle = '#1F2937';
      ctx.fill();
    }

    // Legend
    labels.forEach((label, i) => {
      const legendY = height - 30 + (i % 2) * 15;
      const legendX = 20 + Math.floor(i / 2) * (width / 2);
      ctx.fillStyle = colores[i] || `hsl(${i * 60}, 70%, 50%)`;
      ctx.fillRect(legendX, legendY - 8, 10, 10);
      ctx.fillStyle = '#9CA3AF';
      ctx.font = '10px Arial';
      ctx.textAlign = 'left';
      ctx.fillText(`${label}: ${valores[i]}`, legendX + 15, legendY);
    });
  } else if (tipo === 'bar') {
    const barWidth = chartArea.w / labels.length - 10;
    const maxVal = Math.max(...valores);

    // Grid lines
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = chartArea.y + (chartArea.h * i) / 4;
      ctx.beginPath();
      ctx.moveTo(chartArea.x, y);
      ctx.lineTo(chartArea.x + chartArea.w, y);
      ctx.stroke();
      ctx.fillStyle = '#9CA3AF';
      ctx.font = '10px Arial';
      ctx.textAlign = 'right';
      ctx.fillText(Math.round(maxVal * (4 - i) / 4).toString(), chartArea.x - 5, y + 3);
    }

    valores.forEach((val, i) => {
      const barHeight = (val / maxVal) * chartArea.h;
      const x = chartArea.x + i * (barWidth + 10) + 5;
      const y = chartArea.y + chartArea.h - barHeight;

      // Bar gradient effect
      const gradient = ctx.createLinearGradient(x, y, x, chartArea.y + chartArea.h);
      gradient.addColorStop(0, colores[i] || `hsl(${i * 60}, 70%, 50%)`);
      gradient.addColorStop(1, colores[i] ? colores[i] + '80' : `hsl(${i * 60}, 70%, 30%)`);
      ctx.fillStyle = gradient;
      ctx.fillRect(x, y, barWidth, barHeight);

      // Value on top
      ctx.fillStyle = '#FFFFFF';
      ctx.font = 'bold 11px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(val.toString(), x + barWidth / 2, y - 5);

      // Label
      ctx.fillStyle = '#9CA3AF';
      ctx.font = '9px Arial';
      ctx.fillText(labels[i].substring(0, 10), x + barWidth / 2, chartArea.y + chartArea.h + 15);
    });
  } else if (tipo === 'line') {
    const maxVal = Math.max(...valores);
    const stepX = chartArea.w / (labels.length - 1);

    // Grid
    ctx.strokeStyle = '#374151';
    for (let i = 0; i <= 4; i++) {
      const y = chartArea.y + (chartArea.h * i) / 4;
      ctx.beginPath();
      ctx.moveTo(chartArea.x, y);
      ctx.lineTo(chartArea.x + chartArea.w, y);
      ctx.stroke();
    }

    // Line
    ctx.beginPath();
    ctx.strokeStyle = colores[0] || '#10B981';
    ctx.lineWidth = 3;
    valores.forEach((val, i) => {
      const x = chartArea.x + i * stepX;
      const y = chartArea.y + chartArea.h - (val / maxVal) * chartArea.h;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Points
    valores.forEach((val, i) => {
      const x = chartArea.x + i * stepX;
      const y = chartArea.y + chartArea.h - (val / maxVal) * chartArea.h;
      ctx.beginPath();
      ctx.arc(x, y, 5, 0, 2 * Math.PI);
      ctx.fillStyle = colores[0] || '#10B981';
      ctx.fill();
      ctx.fillStyle = '#FFFFFF';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(val.toString(), x, y - 10);
    });

    // Labels
    ctx.fillStyle = '#9CA3AF';
    ctx.font = '9px Arial';
    labels.forEach((label, i) => {
      ctx.fillText(label.substring(0, 8), chartArea.x + i * stepX, chartArea.y + chartArea.h + 15);
    });
  } else if (tipo === 'gauge') {
    const centerX = width / 2;
    const centerY = chartArea.y + chartArea.h * 0.7;
    const radius = Math.min(chartArea.w, chartArea.h) / 2;
    const value = valores[0] || 0;
    const maxValue = valores[1] || 100;
    const percentage = value / maxValue;

    // Background arc
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, Math.PI, 0);
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 20;
    ctx.stroke();

    // Value arc
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, Math.PI, Math.PI + (Math.PI * percentage));
    ctx.strokeStyle = percentage > 0.7 ? '#10B981' : percentage > 0.4 ? '#F59E0B' : '#EF4444';
    ctx.lineWidth = 20;
    ctx.stroke();

    // Value text
    ctx.fillStyle = '#FFFFFF';
    ctx.font = 'bold 28px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(`${Math.round(percentage * 100)}%`, centerX, centerY - 10);
    ctx.font = '12px Arial';
    ctx.fillStyle = '#9CA3AF';
    ctx.fillText(labels[0] || 'Cumplimiento', centerX, centerY + 15);
  }

  return canvas;
};

// Convert canvas to base64 for jsPDF
const canvasToBase64 = (canvas) => canvas.toDataURL('image/png');

