// Helper para obtener herramientas con URLs desde el database
      const getToolWithUrl = (toolName) => {
        const tool = FREE_TOOLS_DATABASE[toolName];
        if (tool) {
          return { name: toolName, url: tool.url, description: tool.desc };
        }
        return { name: toolName, url: "#", description: toolName };
      };

// Helper para convertir array de nombres a array con URLs
      const mapToolsToUrls = (toolNames) => toolNames.map(getToolWithUrl);

