// Función para generar búsquedas de actualización automática
const generateLearningSearches = (topic, context = "") => {
  const currentYear = new Date().getFullYear();
  const baseQuery = `${topic} ${context} ${currentYear}`.trim();

  return {
    // Búsquedas generales
    googleTrends: `https://trends.google.com/trends/explore?q=${encodeURIComponent(topic)}`,
    googleScholar: `https://scholar.google.com/scholar?q=${encodeURIComponent(baseQuery)}&as_ylo=${currentYear - 1}`,
    googleNews: `https://news.google.com/search?q=${encodeURIComponent(baseQuery)}`,

    // Fuentes especializadas restaurantes
    nraResearch: `https://www.google.com/search?q=site:restaurant.org+${encodeURIComponent(topic)}`,
    nrnNews: `https://www.google.com/search?q=site:nrn.com+${encodeURIComponent(topic)}`,
    qsrMagazine: `https://www.google.com/search?q=site:qsrmagazine.com+${encodeURIComponent(topic)}`,
    technomic: `https://www.google.com/search?q=Technomic+${encodeURIComponent(topic)}`,

    // Business intelligence
    mckinsey: `https://www.google.com/search?q=site:mckinsey.com+${encodeURIComponent(topic)}+restaurant`,
    hbr: `https://www.google.com/search?q=site:hbr.org+${encodeURIComponent(topic)}`,

    // Redes profesionales
    linkedin: `https://www.linkedin.com/search/results/content/?keywords=${encodeURIComponent(topic + " restaurant")}`,

    // Video educativo
    youtube: `https://www.youtube.com/results?search_query=${encodeURIComponent(topic + " restaurant " + currentYear)}`,

    // Podcasts
    podcasts: `https://www.google.com/search?q=${encodeURIComponent(topic + " restaurant podcast " + currentYear)}`
  };
};

