// Función para integrar aprendizaje en reportes de agentes
const integrarAprendizajeEnReporte = (agentCategory) => {
  const agenda = getMonthlyLearningAgenda(agentCategory);
  const tendencias = KNOWLEDGE_BASE.tendenciasIndustria.tendencias.slice(0, 3);
  const herramientas = KNOWLEDGE_BASE.nuevasHerramientas.herramientas.slice(0, 3);

  return {
    seccionAprendizaje: {
      titulo: "📚 APRENDIZAJE CONTINUO Y ACTUALIZACIONES",
      agendaMensual: agenda,
      tendenciasRelevantes: tendencias.map(t => ({
        nombre: t.nombre,
        relevancia: t.relevancia,
        busquedaAutomatica: `https://www.google.com/search?q=${encodeURIComponent(t.busqueda)}`
      })),
      herramientasNuevas: herramientas.map(h => ({
        nombre: h.nombre,
        url: h.url,
        descripcion: h.descripcion
      })),
      proximaRevision: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toLocaleDateString('es-MX'),
      busquedasAutomaticas: generateLearningSearches(agenda.temas[0], "restaurant")
    }
  };
};

// FUNCIÓN: Obtener libro con capacidad de búsqueda automática
const getBookWithSearch = (bookTitle) => {
  const book = BOOKS_DATABASE[bookTitle];
  if (book) {
    return {
      titulo: bookTitle,
      autor: book.autor,
      año: book.año,
      isbn: book.isbn,
      categoria: book.categoria,
      busquedaGoogle: `https://www.google.com/search?q=${encodeURIComponent(book.searchQuery)}`,
      busquedaAmazon: `https://www.amazon.com/s?k=${encodeURIComponent(book.searchQuery)}`,
      busquedaGoogleBooks: `https://books.google.com/books?q=${encodeURIComponent(book.searchQuery)}`
    };
  }
  return { titulo: bookTitle, busquedaGoogle: `https://www.google.com/search?q=${encodeURIComponent(bookTitle + " book")}` };
};

// FUNCIÓN: Mapear array de libros a objetos con búsqueda
const mapBooksToSearchable = (bookTitles) => bookTitles.map(getBookWithSearch);

