// Función para generar instrucciones de análisis de archivo
const generateFileAnalysisInstructions = (fileType, analysisGoal) => {
  const capabilities = FILE_ANALYSIS_CAPABILITIES[fileType];
  if (!capabilities) {
    return {
      error: `Tipo de archivo '${fileType}' no soportado`,
      tiposSoportados: Object.keys(FILE_ANALYSIS_CAPABILITIES)
    };
  }

  return {
    tipoArchivo: fileType,
    extensionesPermitidas: capabilities.extensiones,
    objetivo: analysisGoal,
    pasosAnalisis: [
      `1. Validar que el archivo sea de tipo ${fileType}`,
      `2. Extraer metadatos del archivo`,
      `3. Aplicar análisis de ${Object.keys(capabilities.capacidades).join(", ")}`,
      `4. Generar reporte con: ${capabilities.analisisReporte.join(", ")}`,
      `5. Proporcionar recomendaciones basadas en el análisis`
    ],
    capacidadesDisponibles: capabilities.capacidades,
    formatoReporte: capabilities.analisisReporte
  };
};

// Función para crear prompt de análisis de archivo
const createFileAnalysisPrompt = (fileType, specificTask = "") => {
  const instructions = generateFileAnalysisInstructions(fileType, specificTask);

  return {
    promptBase: `Analiza el archivo ${fileType.toUpperCase()} proporcionado con las siguientes capacidades: ${Object.keys(instructions.capacidadesDisponibles || {}).join(", ")}`,
    tareaEspecifica: specificTask || "Análisis completo",
    instrucciones: instructions,
    formatoRespuesta: {
      resumenEjecutivo: "Breve descripción del contenido",
      hallazgosPrincipales: "Lista de hallazgos clave",
      datosExtraidos: "Datos estructurados extraídos",
      metricasIdentificadas: "Métricas y KPIs encontrados",
      recomendaciones: "Sugerencias basadas en el análisis",
      siguientesPasos: "Acciones recomendadas"
    }
  };
};

