// FUNCIÓN: Obtener fuente de investigación con búsqueda
  const getResearchSource = (sourceName) => {
    const source = RESEARCH_SOURCES_DATABASE[sourceName];
    if (source) {
      return {
        nombre: sourceName,
        tipo: source.tipo,
        busqueda: `https://www.google.com/search?q=${encodeURIComponent(source.searchQuery)}`
      };
    }
    return { nombre: sourceName, busqueda: `https://www.google.com/search?q=${encodeURIComponent(sourceName)}` };
  };

// FUNCIÓN: Mapear fuentes de investigación
  const mapResearchSources = (sourceNames) => sourceNames.map(getResearchSource);

// FUNCIÓN: Obtener plantilla de documento con búsqueda
  const getDocumentTemplate = (templateName) => {
    const template = DOCUMENT_TEMPLATES[templateName];
    if (template) {
      return {
        nombre: templateName,
        categoria: template.categoria,
        formatos: template.formato,
        busquedaTemplate: `https://www.google.com/search?q=${encodeURIComponent(template.searchQuery + " free download")}`,
        busquedaCanva: `https://www.canva.com/search/templates?q=${encodeURIComponent(templateName)}`,
        busquedaNotion: `https://www.notion.so/templates?q=${encodeURIComponent(templateName)}`
      };
    }
    return { nombre: templateName, busqueda: `https://www.google.com/search?q=${encodeURIComponent(templateName + " template free")}` };
  };

// FUNCIÓN: Mapear plantillas de documentos
  const mapDocumentTemplates = (templateNames) => templateNames.map(getDocumentTemplate);

