// Lista de IDs de agentes ocultos (no mostrar en panel)
const AGENTES_OCULTOS = [72];

// Función para verificar si un agente es oculto
const esAgenteOculto = (agenteId) => AGENTES_OCULTOS.includes(parseInt(agenteId));

// Función para obtener agentes visibles (para el panel)
const getAgentesVisibles = () => {
  return Object.values(PERFILES_PROFESIONALES).filter(perfil => !perfil.oculto);
};

// Función para obtener el perfil completo de un agente
const getPerfilAgente = (agenteId) => {
  return PERFILES_PROFESIONALES[agenteId] || null;
};

// Función para buscar agentes por competencia
const buscarPorCompetencia = (competencia) => {
  if (!competencia) return [];
  return Object.values(PERFILES_PROFESIONALES).filter(perfil =>
    perfil && perfil.perfil && perfil.perfil.competencias &&
    Array.isArray(perfil.perfil.competencias) &&
    perfil.perfil.competencias.some(c => c && c.toLowerCase().includes(competencia.toLowerCase()))
    );
};

// Función para buscar agentes por trigger
const buscarPorTrigger = (trigger) => {
  if (!trigger) return [];
  return Object.values(PERFILES_PROFESIONALES).filter(perfil =>
    perfil && perfil.triggers && Array.isArray(perfil.triggers) &&
    perfil.triggers.some(t => t && t.toLowerCase().includes(trigger.toLowerCase()))
    );
};

// Función para obtener herramientas de un perfil
const getHerramientasPerfil = (agenteId) => {
  const perfil = PERFILES_PROFESIONALES[agenteId];
  return perfil && perfil.perfil && perfil.perfil.herramientas ? perfil.perfil.herramientas : [];
};

// Función para obtener la cadena de delegación de un agente
const getCadenaDelegacion = (agenteId, profundidad = 3) => {
  const resultado = [];
  const visitados = new Set();

  const explorar = (id, nivel) => {
    if (nivel > profundidad || visitados.has(id)) return;
    visitados.add(id);

    const perfil = PERFILES_PROFESIONALES[id];
    if (perfil && perfil.delegaA) {
      perfil.delegaA.forEach(delegadoId => {
        const delegado = PERFILES_PROFESIONALES[delegadoId];
        if (delegado) {
          resultado.push({
            nivel,
            desde: perfil.nombre,
            hacia: delegado.nombre,
            categoriaDestino: delegado.categoria
          });
          explorar(delegadoId, nivel + 1);
        }
      });
    }
  };

  explorar(agenteId, 1);
  return resultado;
};

