// Función para obtener alternativa gratuita de una herramienta
                                                                                                                                                                                                              const getHerramientaGratuita = (herramienta) => {
                                                                                                                                                                                                                const alternativa = HERRAMIENTAS_GRATUITAS_ALTERNATIVAS[herramienta];
                                                                                                                                                                                                                if (alternativa) {
                                                                                                                                                                                                                  return alternativa;
                                                                                                                                                                                                                }
  // Si no hay alternativa específica, buscar si ya es gratuita
                                                                                                                                                                                                                const nombreLower = herramienta.toLowerCase();
                                                                                                                                                                                                                if (nombreLower.includes('free') || nombreLower.includes('google')) {
                                                                                                                                                                                                                  return { name: herramienta, url: `https://www.google.com/search?q=${encodeURIComponent(herramienta)}`, gratis: true };
                                                                                                                                                                                                                }
                                                                                                                                                                                                                return null;
                                                                                                                                                                                                              };

// Función para enriquecer las herramientas gratuitas de un agente
                                                                                                                                                                                                              const enriquecerHerramientasGratuitas = (agenteId, freeToolsActuales) => {
                                                                                                                                                                                                                try {
                                                                                                                                                                                                                  const perfil = PERFILES_PROFESIONALES[agenteId];
                                                                                                                                                                                                                  if (!perfil || !perfil.perfil || !perfil.perfil.herramientas) {
                                                                                                                                                                                                                    return freeToolsActuales || [];
                                                                                                                                                                                                                  }

                                                                                                                                                                                                                  const herramientasEnriquecidas = [...(freeToolsActuales || [])];
                                                                                                                                                                                                                  const nombresExistentes = new Set(
                                                                                                                                                                                                                    herramientasEnriquecidas
                                                                                                                                                                                                                    .filter(t => t && t.name)
                                                                                                                                                                                                                    .map(t => t.name.toLowerCase())
                                                                                                                                                                                                                    );

                                                                                                                                                                                                                  perfil.perfil.herramientas.forEach(herramienta => {
                                                                                                                                                                                                                    if (!herramienta) return;
                                                                                                                                                                                                                    const alternativa = getHerramientaGratuita(herramienta);
                                                                                                                                                                                                                    if (alternativa && alternativa.gratis && alternativa.name && !nombresExistentes.has(alternativa.name.toLowerCase())) {
                                                                                                                                                                                                                      herramientasEnriquecidas.push({
                                                                                                                                                                                                                        name: alternativa.name,
                                                                                                                                                                                                                        url: alternativa.url || '#',
                                                                                                                                                                                                                        fromPerfil: true,
                                                                                                                                                                                                                        originalTool: herramienta
                                                                                                                                                                                                                      });
                                                                                                                                                                                                                      nombresExistentes.add(alternativa.name.toLowerCase());
                                                                                                                                                                                                                    }
                                                                                                                                                                                                                  });

                                                                                                                                                                                                                  return herramientasEnriquecidas;
                                                                                                                                                                                                                } catch (error) {
                                                                                                                                                                                                                  console.error('Error enriqueciendo herramientas para agente', agenteId, error);
                                                                                                                                                                                                                  return freeToolsActuales || [];
                                                                                                                                                                                                                }
                                                                                                                                                                                                              };

// Enriquecer todos los agentes con sus perfiles profesionales
                                                                                                                                                                                                              try {
                                                                                                                                                                                                                Object.keys(AGENTS).forEach(agenteId => {
                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                    const id = parseInt(agenteId);
                                                                                                                                                                                                                    if (isNaN(id) || !AGENTS[id]) return;

                                                                                                                                                                                                                    const perfil = PERFILES_PROFESIONALES[id];

                                                                                                                                                                                                                    if (perfil && perfil.perfil) {
        // Agregar perfil profesional completo al agente
                                                                                                                                                                                                                      AGENTS[id].perfilProfesional = {
                                                                                                                                                                                                                        ...(perfil.perfil || {}),
                                                                                                                                                                                                                        experiencia: perfil.experiencia || {},
                                                                                                                                                                                                                        nombreCorto: perfil.nombreCorto || '',
                                                                                                                                                                                                                        categoria: perfil.categoria || '',
                                                                                                                                                                                                                        descripcionExtendida: perfil.descripcion || '',
                                                                                                                                                                                                                        triggers: perfil.triggers || [],
                                                                                                                                                                                                                        delegaA: perfil.delegaA || [],
                                                                                                                                                                                                                        kpis: perfil.perfil?.kpis || [],
                                                                                                                                                                                                                        logros: perfil.perfil?.logros || [],
                                                                                                                                                                                                                        metodologias: perfil.perfil?.metodologias || []
                                                                                                                                                                                                                      };

        // Enriquecer herramientas gratuitas con las del perfil
                                                                                                                                                                                                                      if (AGENTS[id].freeTools && Array.isArray(AGENTS[id].freeTools)) {
                                                                                                                                                                                                                        AGENTS[id].freeTools = enriquecerHerramientasGratuitas(id, AGENTS[id].freeTools);
                                                                                                                                                                                                                      }
                                                                                                                                                                                                                    }
                                                                                                                                                                                                                  } catch (agentError) {
                                                                                                                                                                                                                    console.error('Error procesando agente', agenteId, agentError);
                                                                                                                                                                                                                  }
                                                                                                                                                                                                                });
} catch (error) {
  console.error('Error en enriquecimiento de agentes:', error);
}

// Función de utilidad para buscar el mejor agente según tema
const encontrarAgentesPorTema = (tema) => {
  if (!tema) return [];
  const resultados = [];

  try {
    Object.values(AGENTS).forEach(agente => {
      try {
        if (!agente || !agente.id) return;
        const perfil = PERFILES_PROFESIONALES[agente.id];
        if (!perfil || !perfil.perfil) return;

        let relevancia = 0;
        const temaLower = tema.toLowerCase();

        // Buscar en triggers
        if (perfil.triggers && Array.isArray(perfil.triggers) &&
          perfil.triggers.some(t => t && t.toLowerCase().includes(temaLower))) {
          relevancia += 10;
      }

        // Buscar en competencias
      if (perfil.perfil.competencias && Array.isArray(perfil.perfil.competencias) &&
        perfil.perfil.competencias.some(c => c && c.toLowerCase().includes(temaLower))) {
        relevancia += 5;
    }

        // Buscar en descripción
    if (perfil.descripcion && perfil.descripcion.toLowerCase().includes(temaLower)) {
      relevancia += 3;
    }

        // Buscar en nombre
    if (agente.name && agente.name.toLowerCase().includes(temaLower)) {
      relevancia += 8;
    }

    if (relevancia > 0) {
      resultados.push({
        agente,
        perfil,
        relevancia
      });
    }
  } catch (agentError) {
    console.error('Error buscando agente:', agentError);
  }
});
  } catch (error) {
    console.error('Error en búsqueda por tema:', error);
  }

  return resultados.sort((a, b) => b.relevancia - a.relevancia);
};

// Exportar funciones de utilidad para uso externo
const VERTICE_UTILS = {
  getPerfilAgente,
  buscarPorCompetencia,
  buscarPorTrigger,
  getHerramientasPerfil,
  getCadenaDelegacion,
  encontrarAgentesPorTema,
  getHerramientaGratuita,
  enriquecerHerramientasGratuitas,
  HERRAMIENTAS_GRATUITAS_ALTERNATIVAS,
  PERFILES_PROFESIONALES
};

