// Agent Icon Component with gradient
const AgentIcon = ({ category, size = "w-8 h-8" }) => {
  const Icon = CategoryIcons[category];
  const colors = {
    financial: "from-[#C0A062] to-[#A68B4B]",
    marketing: "from-violet-400 to-purple-600",
    operational: "from-blue-400 to-indigo-600",
    hr: "from-amber-400 to-yellow-600",
    customer: "from-pink-400 to-rose-600",
    strategy: "from-indigo-400 to-violet-600",
    compliance: "from-red-400 to-rose-600",
    technology: "from-cyan-400 to-teal-600",
    legal: "from-slate-500 to-gray-700"
  };

  return (
    <div className={`${size} rounded-xl bg-gradient-to-br ${colors[category] || 'from-gray-400 to-gray-600'} p-1.5 shadow-lg`}>
    <div className="w-full h-full text-white">
    {Icon ? <Icon /> : null}
    </div>
    </div>
    );
};

