// ============================================================================
// SISTEMA DE AUTO-DIAGNÓSTICO INTELIGENTE - NIVEL PROGRAMADOR SENIOR 20x
// ============================================================================
// Este sistema verifica automáticamente la integridad del sistema al iniciar
// Un programador senior SIEMPRE implementa verificaciones de consistencia

const SYSTEM_DIAGNOSTIC = {
  version: "2.0.0",
  lastCheck: null,

  // Configuración del sistema
  config: {
    TOTAL_AGENTS: 72,
    TOTAL_CATEGORIES: 14,
    MIN_WORKFLOWS: 78,
    CEO_AGENT_ID: 1,
    PM_AGENT_ID: 56
  },

  // Ejecutar diagnóstico completo
  runFullDiagnostic: function(agents, workflows) {
    const results = {
      timestamp: new Date().toISOString(),
      passed: true,
      criticalErrors: [],
      warnings: [],
      info: [],
      metrics: {}
    };

    // 1. VALIDAR AGENTES
    const agentCheck = this.validateAgents(agents);
    results.metrics.agents = agentCheck.metrics;
    if (agentCheck.errors.length > 0) {
      results.criticalErrors.push(...agentCheck.errors);
      results.passed = false;
    }
    results.warnings.push(...agentCheck.warnings);
    results.info.push(...agentCheck.info);

    // 2. VALIDAR DELEGACIÓN
    const delegationCheck = this.validateDelegation(agents);
    results.metrics.delegation = delegationCheck.metrics;
    if (delegationCheck.errors.length > 0) {
      results.criticalErrors.push(...delegationCheck.errors);
      results.passed = false;
    }
    results.warnings.push(...delegationCheck.warnings);

    // 3. VALIDAR WORKFLOWS
    const workflowCheck = this.validateWorkflows(workflows, agents);
    results.metrics.workflows = workflowCheck.metrics;
    if (workflowCheck.errors.length > 0) {
      results.criticalErrors.push(...workflowCheck.errors);
      results.passed = false;
    }
    results.warnings.push(...workflowCheck.warnings);

    // 4. VALIDAR CEO
    const ceoCheck = this.validateCEO(agents);
    results.metrics.ceo = ceoCheck.metrics;
    if (ceoCheck.errors.length > 0) {
      results.criticalErrors.push(...ceoCheck.errors);
      results.passed = false;
    }
    results.warnings.push(...ceoCheck.warnings);

    // 5. VALIDAR SYSTEM PROMPTS
    const promptCheck = this.validateSystemPrompts(agents);
    results.metrics.prompts = promptCheck.metrics;
    results.warnings.push(...promptCheck.warnings);

    this.lastCheck = results;
    return results;
  },

  // Validar todos los agentes
  validateAgents: function(agents) {
    const result = { errors: [], warnings: [], info: [], metrics: {} };
    const agentIds = Object.keys(agents).map(Number);

    result.metrics.total = agentIds.length;
    result.metrics.expected = this.config.TOTAL_AGENTS;
    result.metrics.missing = [];
    result.metrics.withSystemPrompt = 0;
    result.metrics.withoutSystemPrompt = [];
    result.metrics.withTools = 0;
    result.metrics.categories = {};

    // Verificar total de agentes
    if (agentIds.length !== this.config.TOTAL_AGENTS) {
      result.warnings.push({
        type: 'AGENT_COUNT_MISMATCH',
        message: `Se esperaban ${this.config.TOTAL_AGENTS} agentes, se encontraron ${agentIds.length}`,
        severity: 'warning'
      });
    }

    // Verificar IDs consecutivos 1-72
    for (let i = 1; i <= this.config.TOTAL_AGENTS; i++) {
      if (!agents[i]) {
        result.metrics.missing.push(i);
        result.errors.push({
          type: 'MISSING_AGENT',
          message: `Agente ID ${i} no existe`,
          severity: 'critical'
        });
      } else {
        // Verificar propiedades requeridas
        const agent = agents[i];

        if (!agent.name) {
          result.errors.push({
            type: 'AGENT_NO_NAME',
            message: `Agente ID ${i} no tiene nombre`,
            severity: 'critical'
          });
        }

        if (!agent.systemPrompt) {
          result.metrics.withoutSystemPrompt.push(i);
        } else {
          result.metrics.withSystemPrompt++;
        }

        if (agent.tools && agent.tools.length > 0) {
          result.metrics.withTools++;
        }

        // Contar por categoría
        const category = agent.category || 'unknown';
        result.metrics.categories[category] = (result.metrics.categories[category] || 0) + 1;
      }
    }

    // Advertir sobre agentes sin systemPrompt (excepto algunos específicos)
    const criticalAgentsWithoutPrompt = result.metrics.withoutSystemPrompt.filter(id =>
      id !== 1 // El CEO ahora tiene, pero algunos otros pueden no necesitarlo
      );

    if (result.metrics.withoutSystemPrompt.length > 0) {
      result.info.push({
        type: 'AGENTS_WITHOUT_SYSTEMPROMPT',
        message: `${result.metrics.withoutSystemPrompt.length} agentes sin systemPrompt personalizado: [${result.metrics.withoutSystemPrompt.join(', ')}]`,
        severity: 'info'
      });
    }

    return result;
  },

  // Validar sistema de delegación
  validateDelegation: function(agents) {
    const result = { errors: [], warnings: [], metrics: {} };

    result.metrics.agentsWithDelegation = 0;
    result.metrics.totalDelegations = 0;
    result.metrics.invalidDelegations = [];
    result.metrics.ceoCanDelegateTo = [];

    Object.entries(agents).forEach(([id, agent]) => {
      const agentId = parseInt(id);

      if (agent.canDelegateTo && agent.canDelegateTo.length > 0) {
        result.metrics.agentsWithDelegation++;
        result.metrics.totalDelegations += agent.canDelegateTo.length;

        // Verificar que todos los IDs de delegación existen
        agent.canDelegateTo.forEach(delegateId => {
          if (!agents[delegateId]) {
            result.metrics.invalidDelegations.push({ from: agentId, to: delegateId });
            result.errors.push({
              type: 'INVALID_DELEGATION',
              message: `Agente ${agentId} (${agent.name}) delega a agente inexistente: ${delegateId}`,
              severity: 'critical'
            });
          }
        });

        // Registrar delegaciones del CEO
        if (agentId === this.config.CEO_AGENT_ID) {
          result.metrics.ceoCanDelegateTo = agent.canDelegateTo;
        }
      }
    });

    // Verificar que el CEO puede delegar a todos los agentes
    const ceo = agents[this.config.CEO_AGENT_ID];
    if (ceo && ceo.canDelegateTo) {
      const missingDelegations = [];
      for (let i = 2; i <= this.config.TOTAL_AGENTS; i++) {
        if (!ceo.canDelegateTo.includes(i)) {
          missingDelegations.push(i);
        }
      }

      if (missingDelegations.length > 0) {
        result.warnings.push({
          type: 'CEO_INCOMPLETE_DELEGATION',
          message: `CEO no puede delegar a ${missingDelegations.length} agentes: [${missingDelegations.slice(0, 10).join(', ')}${missingDelegations.length > 10 ? '...' : ''}]`,
          severity: 'warning'
        });
      } else {
        result.metrics.ceoFullDelegation = true;
      }
    }

    return result;
  },

  // Validar workflows
  validateWorkflows: function(workflows, agents) {
    const result = { errors: [], warnings: [], metrics: {} };

    result.metrics.total = workflows.length;
    result.metrics.expected = this.config.MIN_WORKFLOWS;
    result.metrics.invalidSteps = [];
    result.metrics.averageSteps = 0;
    result.metrics.workflowsWithPM = 0;

    let totalSteps = 0;

    workflows.forEach((workflow, index) => {
      // Verificar estructura básica
      if (!workflow.id || !workflow.name || !workflow.steps) {
        result.errors.push({
          type: 'INVALID_WORKFLOW_STRUCTURE',
          message: `Workflow índice ${index} tiene estructura inválida`,
          severity: 'critical'
        });
        return;
      }

      totalSteps += workflow.steps.length;

      // Verificar si incluye PM (agente 56)
      if (workflow.steps.includes(this.config.PM_AGENT_ID)) {
        result.metrics.workflowsWithPM++;
      }

      // Verificar que todos los pasos son agentes válidos
      workflow.steps.forEach((stepId, stepIndex) => {
        if (!agents[stepId]) {
          result.metrics.invalidSteps.push({
            workflowId: workflow.id,
            workflowName: workflow.name,
            stepIndex,
            invalidAgentId: stepId
          });
          result.errors.push({
            type: 'INVALID_WORKFLOW_STEP',
            message: `Workflow "${workflow.name}" (ID:${workflow.id}) paso ${stepIndex + 1} referencia agente inexistente: ${stepId}`,
            severity: 'critical'
          });
        }
      });
    });

    result.metrics.averageSteps = workflows.length > 0 ? (totalSteps / workflows.length).toFixed(1) : 0;

    // Advertencia si hay pocos workflows
    if (workflows.length < this.config.MIN_WORKFLOWS) {
      result.warnings.push({
        type: 'LOW_WORKFLOW_COUNT',
        message: `Solo ${workflows.length} workflows definidos (mínimo esperado: ${this.config.MIN_WORKFLOWS})`,
        severity: 'warning'
      });
    }

    return result;
  },

  // Validar configuración del CEO
  validateCEO: function(agents) {
    const result = { errors: [], warnings: [], metrics: {} };
    const ceo = agents[this.config.CEO_AGENT_ID];

    if (!ceo) {
      result.errors.push({
        type: 'CEO_NOT_FOUND',
        message: 'El agente CEO (ID 1) no existe',
        severity: 'critical'
      });
      return result;
    }

    result.metrics.hasSystemPrompt = !!ceo.systemPrompt;
    result.metrics.hasTools = ceo.tools && ceo.tools.length > 0;
    result.metrics.toolsCount = ceo.tools ? ceo.tools.length : 0;
    result.metrics.canDelegateCount = ceo.canDelegateTo ? ceo.canDelegateTo.length : 0;
    result.metrics.hasFrameworks = !!ceo.frameworksEstrategicos;
    result.metrics.hasTriada = !!ceo.sistemaTriadaDecisiones;
    result.metrics.hasLearning = !!ceo.sistemaAprendizaje;

    // Verificar systemPrompt del CEO
    if (!ceo.systemPrompt) {
      result.errors.push({
        type: 'CEO_NO_SYSTEMPROMPT',
        message: 'El CEO no tiene systemPrompt - no podrá analizar y delegar automáticamente',
        severity: 'critical'
      });
    } else {
      // Verificar contenido del systemPrompt del CEO
      const promptLower = ceo.systemPrompt.toLowerCase();
      const requiredKeywords = ['analizar', 'delegar', 'workflow', 'agente'];
      const missingKeywords = requiredKeywords.filter(kw => !promptLower.includes(kw));

      if (missingKeywords.length > 0) {
        result.warnings.push({
          type: 'CEO_INCOMPLETE_PROMPT',
          message: `SystemPrompt del CEO podría estar incompleto - falta: ${missingKeywords.join(', ')}`,
          severity: 'warning'
        });
      }
    }

    // Verificar delegación completa del CEO
    if (!ceo.canDelegateTo || ceo.canDelegateTo.length < this.config.TOTAL_AGENTS - 1) {
      result.warnings.push({
        type: 'CEO_LIMITED_DELEGATION',
        message: `CEO solo puede delegar a ${ceo.canDelegateTo ? ceo.canDelegateTo.length : 0} de ${this.config.TOTAL_AGENTS - 1} agentes`,
        severity: 'warning'
      });
    }

    return result;
  },

  // Validar system prompts de todos los agentes
  validateSystemPrompts: function(agents) {
    const result = { errors: [], warnings: [], metrics: {} };

    result.metrics.withPrompt = 0;
    result.metrics.withoutPrompt = [];
    result.metrics.avgPromptLength = 0;
    result.metrics.shortPrompts = [];

    let totalLength = 0;
    let promptCount = 0;

    Object.entries(agents).forEach(([id, agent]) => {
      const agentId = parseInt(id);

      if (agent.systemPrompt) {
        result.metrics.withPrompt++;
        promptCount++;
        totalLength += agent.systemPrompt.length;

        // Advertir si el prompt es muy corto
        if (agent.systemPrompt.length < 200) {
          result.metrics.shortPrompts.push({
            id: agentId,
            name: agent.name,
            length: agent.systemPrompt.length
          });
        }
      } else {
        result.metrics.withoutPrompt.push({
          id: agentId,
          name: agent.name
        });
      }
    });

    result.metrics.avgPromptLength = promptCount > 0 ? Math.round(totalLength / promptCount) : 0;

    // Advertir si muchos agentes no tienen prompt
    if (result.metrics.withoutPrompt.length > 30) {
      result.warnings.push({
        type: 'MANY_AGENTS_WITHOUT_PROMPT',
        message: `${result.metrics.withoutPrompt.length} agentes sin systemPrompt personalizado`,
        severity: 'warning'
      });
    }

    return result;
  },

  // Generar reporte de salud del sistema
  generateHealthReport: function(agents, workflows) {
    const diagnostic = this.runFullDiagnostic(agents, workflows);

    const report = {
      status: diagnostic.passed ? '✅ SISTEMA SALUDABLE' : '❌ ERRORES CRÍTICOS DETECTADOS',
      timestamp: diagnostic.timestamp,
      summary: {
        totalAgents: diagnostic.metrics.agents.total,
        totalWorkflows: diagnostic.metrics.workflows.total,
        criticalErrors: diagnostic.criticalErrors.length,
        warnings: diagnostic.warnings.length
      },
      details: diagnostic
    };

    // Log en consola para desarrollo
    if (typeof console !== 'undefined') {
      console.group('🔍 VÉRTICE GASTRONÓMICO - Diagnóstico del Sistema');
      console.log(report.status);
      console.log(`📊 Agentes: ${report.summary.totalAgents}/${this.config.TOTAL_AGENTS}`);
      console.log(`📋 Workflows: ${report.summary.totalWorkflows}`);
      console.log(`🎯 CEO puede delegar a: ${diagnostic.metrics.delegation.ceoCanDelegateTo?.length || 0} agentes`);
      console.log(`📝 Agentes con systemPrompt: ${diagnostic.metrics.prompts.withPrompt}`);

      if (diagnostic.criticalErrors.length > 0) {
        console.group('❌ Errores Críticos');
        diagnostic.criticalErrors.forEach(e => console.error(`[${e.type}] ${e.message}`));
        console.groupEnd();
      }

      if (diagnostic.warnings.length > 0) {
        console.group('⚠️ Advertencias');
        diagnostic.warnings.forEach(w => console.warn(`[${w.type}] ${w.message}`));
        console.groupEnd();
      }

      console.groupEnd();
    }

    return report;
  },

  // ============================================================================
  // SISTEMA DE REGISTRO DE CORRECCIONES Y APRENDIZAJE CONTINUO
  // ============================================================================
  // Integración con el Framework de Aprendizaje Continuo Vértice
  // Un programador senior 20x siempre registra y aprende de las correcciones

  correctionHistory: [],

  // Registrar una corrección realizada al sistema
  registerCorrection: function(correction) {
    const record = {
      id: `CORR-${Date.now()}`,
      timestamp: new Date().toISOString(),
      type: correction.type || 'general',
      component: correction.component || 'unknown',
      description: correction.description,
      beforeState: correction.beforeState || null,
      afterState: correction.afterState || null,
      impact: correction.impact || 'medium',
      learnedLesson: correction.learnedLesson || null,
      preventionMeasures: correction.preventionMeasures || [],
      relatedAgents: correction.relatedAgents || [],
      relatedWorkflows: correction.relatedWorkflows || []
    };

    this.correctionHistory.push(record);

    // Log para seguimiento
    if (typeof console !== 'undefined') {
      console.log(`📝 [APRENDIZAJE] Corrección registrada: ${record.id}`);
      console.log(`   Tipo: ${record.type}`);
      console.log(`   Componente: ${record.component}`);
      console.log(`   Descripción: ${record.description}`);
      if (record.learnedLesson) {
        console.log(`   📚 Lección aprendida: ${record.learnedLesson}`);
      }
    }

    return record;
  },

  // Obtener historial de correcciones
  getCorrectionHistory: function(filters = {}) {
    let history = [...this.correctionHistory];

    if (filters.type) {
      history = history.filter(c => c.type === filters.type);
    }
    if (filters.component) {
      history = history.filter(c => c.component === filters.component);
    }
    if (filters.since) {
      history = history.filter(c => new Date(c.timestamp) >= new Date(filters.since));
    }

    return history;
  },

  // Generar reporte de aprendizaje del sistema
  generateLearningReport: function() {
    const totalCorrections = this.correctionHistory.length;
    const correctionsByType = {};
    const correctionsByComponent = {};
    const lessons = [];

    this.correctionHistory.forEach(c => {
      correctionsByType[c.type] = (correctionsByType[c.type] || 0) + 1;
      correctionsByComponent[c.component] = (correctionsByComponent[c.component] || 0) + 1;
      if (c.learnedLesson) {
        lessons.push({
          lesson: c.learnedLesson,
          context: c.description,
          date: c.timestamp
        });
      }
    });

    return {
      titulo: "📊 REPORTE DE APRENDIZAJE CONTINUO DEL SISTEMA",
      timestamp: new Date().toISOString(),
      resumen: {
        totalCorrecciones: totalCorrections,
        correccionesPorTipo: correctionsByType,
        correccionesPorComponente: correctionsByComponent
      },
      leccionesAprendidas: lessons,
      recomendaciones: this.generateRecommendations(correctionsByType, correctionsByComponent),
      estadoSistema: totalCorrections === 0 ? 'Sin correcciones registradas' :
      totalCorrections < 5 ? 'Sistema estable' :
      totalCorrections < 10 ? 'Sistema en evolución' : 'Sistema maduro con historial de mejoras'
    };
  },

  // Generar recomendaciones basadas en el historial
  generateRecommendations: function(byType, byComponent) {
    const recommendations = [];

    // Analizar patrones por tipo
    if (byType['syntax'] > 2) {
      recommendations.push({
        prioridad: 'alta',
        area: 'Sintaxis del código',
        recomendacion: 'Implementar linter más estricto y pre-commit hooks',
        accion: 'Configurar ESLint con reglas más estrictas'
      });
    }

    if (byType['template_literal'] > 1) {
      recommendations.push({
        prioridad: 'alta',
        area: 'Template literals',
        recomendacion: 'Evitar escape manual de backticks en template literals',
        accion: 'Usar funciones helper o tagged templates'
      });
    }

    // Analizar patrones por componente
    if (byComponent['SYSTEM_DIAGNOSTIC'] > 1) {
      recommendations.push({
        prioridad: 'media',
        area: 'Sistema de diagnóstico',
        recomendacion: 'El módulo SYSTEM_DIAGNOSTIC ha requerido múltiples correcciones',
        accion: 'Considerar agregar tests unitarios específicos'
      });
    }

    if (byComponent['agents'] > 3) {
      recommendations.push({
        prioridad: 'media',
        area: 'Definición de agentes',
        recomendacion: 'Múltiples correcciones en agentes',
        accion: 'Crear schema de validación para nuevos agentes'
      });
    }

    // Recomendación general si hay pocas correcciones
    if (Object.keys(byType).length === 0) {
      recommendations.push({
        prioridad: 'info',
        area: 'General',
        recomendacion: 'No hay correcciones registradas aún',
        accion: 'Usar registerCorrection() para documentar mejoras futuras'
      });
    }

    return recommendations;
  },

  // Competencias del sistema de diagnóstico (nivel Programador Senior 20x)
  competencias: {
    version: "2.0.0",
    nivel: "Programador Senior 20x",
    experiencia: [
      "Validación de integridad de sistemas multi-agente",
      "Detección de inconsistencias en delegación",
      "Verificación de systemPrompts y herramientas",
      "Análisis de workflows y dependencias",
      "Registro y análisis de correcciones",
      "Generación de reportes de aprendizaje"
    ],
    alcances: [
      "Diagnóstico completo del sistema Vértice (72 agentes, 78+ workflows)",
      "Validación de configuración del CEO y cadena de delegación",
      "Detección de errores críticos y advertencias",
      "Integración con framework de Aprendizaje Continuo",
      "Generación de métricas de salud del sistema",
      "Recomendaciones basadas en historial de correcciones"
    ],
    mejoraContinua: {
      descripcion: "El sistema aprende de cada corrección realizada",
      mecanismos: [
        "Registro automático de correcciones con registerCorrection()",
        "Análisis de patrones en historial de errores",
        "Generación de recomendaciones preventivas",
        "Documentación de lecciones aprendidas"
      ],
      ultimaActualizacion: new Date().toISOString().split('T')[0]
    }
  }
};

