// Helper to count agents per category
const getCategoryCounts = () => {
  const counts = { all: Object.keys(AGENTS).length };
  Object.keys(CATEGORIES).forEach(cat => {
    counts[cat] = Object.values(AGENTS).filter(a => a.category === cat).length;
  });
  return counts;
};

// Helper to count unique agents in workflow
const getUniqueAgentCount = (steps) => new Set(steps).size;

// Export functions
const exportToJSON = (data, filename, autoDownload = true) => {
  const json = JSON.stringify(data, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  if (autoDownload) {
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
  }
  return { blob, url, filename };
};

const exportToCSV = (agents, filename, autoDownload = true) => {
  const headers = ['ID', 'Nombre', 'Categoría', 'Descripción', 'Herramientas', 'Puede Delegar A'];
  const rows = agents.map(a => [
    a.id,
    a.name,
    CATEGORIES[a.category]?.name || a.category,
    a.description,
    a.tools.join('; '),
    a.canDelegateTo.join('; ')
  ]);

  const csvContent = [headers, ...rows]
  .map(row => row.map(cell => `"${cell}"`).join(','))
  .join('\n');

  const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  if (autoDownload) {
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
  }
  return { blob, url, filename };
};

const exportAgentToPDF = (agent) => {
  const doc = new jsPDF();
  const category = CATEGORIES[agent.category];
  const isLegalAgent = agent.category === 'legal';

  let startY = 20;

  // Corporate Header (solo para agentes NO legales)
  if (!isLegalAgent) {
    // Header background
    doc.setFillColor(31, 41, 55); // Dark gray #1F2937
    doc.rect(0, 0, 210, 35, 'F');

    // Gold accent line
    doc.setFillColor(192, 160, 98); // Gold #C0A062
    doc.rect(0, 35, 210, 2, 'F');

    // Company name
    doc.setFontSize(18);
    doc.setTextColor(212, 184, 122); // Light gold #D4B87A
    doc.text('VÉRTICE GASTRONÓMICO', 20, 15);

    // Tagline
    doc.setFontSize(9);
    doc.setTextColor(156, 163, 175); // Gray #9CA3AF
    doc.text('Estrategia Gastronómica | Sistema Multi-Agente IA', 20, 23);

    // Document type badge
    doc.setFillColor(192, 160, 98);
    doc.roundedRect(150, 8, 45, 18, 3, 3, 'F');
    doc.setFontSize(8);
    doc.setTextColor(31, 41, 55);
    doc.text('FICHA TÉCNICA', 155, 16);
    doc.text('DE AGENTE', 159, 22);

    startY = 50;
  }

  // Title
  doc.setFontSize(18);
  doc.setTextColor(192, 160, 98); // Vértice gold #C0A062
  doc.text(`Agente #${agent.id}: ${agent.name}`, 20, startY);

  // Category badge
  doc.setFontSize(10);
  doc.setTextColor(100);
  doc.text(`${category?.icon || ''} Categoría: ${category?.name || agent.category}`, 20, startY + 10);

  // Description
  doc.setFontSize(11);
  doc.setTextColor(80);
  const descLines = doc.splitTextToSize(agent.description, 170);
  doc.text(descLines, 20, startY + 20);

  // Tools section
  const toolsY = startY + 20 + (descLines.length * 6) + 10;
  doc.setFontSize(13);
  doc.setTextColor(16, 185, 129); // Green
  doc.text(`Herramientas (${agent.tools.length}):`, 20, toolsY);
  doc.setFontSize(10);
  doc.setTextColor(60);
  agent.tools.forEach((tool, i) => {
    doc.text(`• ${tool}`, 25, toolsY + 8 + (i * 6));
  });

  // Delegates section
  const delegateY = toolsY + 8 + (agent.tools.length * 6) + 8;
  doc.setFontSize(13);
  doc.setTextColor(147, 51, 234); // purple
  doc.text(`Puede delegar a (${agent.canDelegateTo.length} agentes):`, 20, delegateY);

  const delegateNames = agent.canDelegateTo.slice(0, 10).map(id => {
    const a = AGENTS[id];
    return a ? `#${a.id} ${a.name}` : `#${id}`;
  });

  doc.setFontSize(9);
  doc.setTextColor(60);
  delegateNames.forEach((name, i) => {
    doc.text(`• ${name}`, 25, delegateY + 7 + (i * 5));
  });

  if (agent.canDelegateTo.length > 10) {
    doc.text(`... y ${agent.canDelegateTo.length - 10} más`, 25, delegateY + 7 + (10 * 5));
  }

  // Benchmarks
  if (agent.benchmarks) {
    const benchY = delegateY + 7 + (Math.min(agent.canDelegateTo.length, 10) * 5) + 12;
    doc.setFontSize(13);
    doc.setTextColor(234, 179, 8); // yellow
    doc.text('Benchmarks:', 20, benchY);
    doc.setFontSize(10);
    doc.setTextColor(60);
    Object.entries(agent.benchmarks).forEach(([key, value], i) => {
      doc.text(`• ${key}: ${value}`, 25, benchY + 7 + (i * 6));
    });
  }

  // Corporate Footer (solo para agentes NO legales)
  if (!isLegalAgent) {
    // Footer background
    doc.setFillColor(31, 41, 55);
    doc.rect(0, 275, 210, 22, 'F');

    // Gold accent line
    doc.setFillColor(192, 160, 98);
    doc.rect(0, 275, 210, 1, 'F');

    // Footer text
    doc.setFontSize(8);
    doc.setTextColor(156, 163, 175);
    doc.text('Vértice Gastronómico - Estrategia Gastronómica', 20, 283);
    doc.text('Sistema Multi-Agente v4.0 | Documento Confidencial', 20, 289);

    // Date on right
    doc.setTextColor(192, 160, 98);
    doc.text(new Date().toLocaleDateString('es-MX', { year: 'numeric', month: 'long', day: 'numeric' }), 150, 286);
  } else {
    // Simple footer for legal agents
    doc.setFontSize(9);
    doc.setTextColor(150);
    doc.text('Sistema Multi-Agente v4.0', 20, 285);
    doc.text(new Date().toLocaleDateString('es-MX'), 170, 285);
  }

  const filename = `agente_${agent.id}_${agent.name.replace(/\s+/g, '_')}.pdf`;
  const blob = doc.output('blob');
  const url = URL.createObjectURL(blob);
  doc.save(filename);
  return { blob, url, filename, name: `Agente ${agent.id}: ${agent.name}`, type: 'pdf' };
};

// Export agent to Word document
