  useEffect(() => {
    const checkConnection = async () => {
      try {
        const response = await fetch(`${import.meta.env.VITE_API_URL || 'http://localhost:3001'}/api/health`, {
          method: 'GET',
          signal: AbortSignal.timeout(5000)
        });
        if (response.ok) {
          setConnectionStatus(prev => prev !== 'online' ? 'online' : prev);
        } else {
          setConnectionStatus('offline');
        }
      } catch (error) {
        setConnectionStatus(prev => prev === 'online' ? 'reconnecting' : 'offline');
      }
    };

    // Initial check
    checkConnection();

    // Check every 30 seconds
    connectionCheckRef.current = setInterval(checkConnection, 30000);

    // Also check on window focus
    const handleFocus = () => checkConnection();
    window.addEventListener('focus', handleFocus);

    return () => {
      if (connectionCheckRef.current) clearInterval(connectionCheckRef.current);
      window.removeEventListener('focus', handleFocus);
    };
  }, []);

