  // Process instruction with Claude
  const processInstruction = useCallback(async (agentId) => {
    const instruction = agentInstructions[agentId];
    if (!instruction?.trim()) return;

    const agent = AGENTS[agentId];
    if (!agent) return;

    setProcessingInstruction(agentId);

    try {
      // CRÍTICO: Recuperar documentos completos de IndexedDB antes de enviar
      // Los archivos grandes tienen data='[STORED_IN_INDEXEDDB]' en el estado
      const docsFromState = agentDocuments[agentId] || [];
      const documentsToSend = await Promise.all(
        docsFromState.map(async (doc) => {
          if (doc.data === '[STORED_IN_INDEXEDDB]') {
            // Recuperar documento completo de IndexedDB
            const fullDoc = await getDocumentFromDB(doc.id);
            if (fullDoc && fullDoc.data) {
              console.log(`[DOCS] Recuperado de IndexedDB: ${doc.name}`);
              return fullDoc;
            }
            console.warn(`[DOCS] No se pudo recuperar de IndexedDB: ${doc.name}`);
            return doc; // Devolver el original si falla
          }
          return doc; // Ya tiene los datos
        })
        );

      console.log(`[DOCS] Enviando ${documentsToSend.length} documentos al servidor`);

      const response = await fetch(`${API_URL}/api/process-instruction`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          instruction,
          agentId,
          agentName: agent.name,
          agentDescription: agent.description,
          agentTools: agent.tools,
          agentCategory: agent.category,
          agentSystemPrompt: agent.systemPrompt, // Enviar el systemPrompt específico del agente
          documents: documentsToSend
        })
      });

      if (response.ok) {
        const result = await response.json();
        const responseData = {
          ...result,
          timestamp: new Date().toISOString()
        };
        // CORRECCIÓN: Guardar respuesta en el agente SELECCIONADO (para que se muestre en UI)
        // El campo agentId dentro de responseData indica quién realmente procesó
        const processedAgentId = (responseData.agentId && Number.isFinite(parseInt(responseData.agentId)))
        ? parseInt(responseData.agentId)
        : agentId;

// Guardar en el agente procesador
        setInstructionResponse(prev => ({
          ...prev,
          [processedAgentId]: responseData,
  // También conservar una copia en el agente seleccionado
          ...(processedAgentId !== agentId ? { [agentId]: { ...responseData, processedByAgentId: processedAgentId } } : {})
        }));

        saveToHistory(processedAgentId, instruction, responseData);
        if (processedAgentId !== agentId) {
          saveToHistory(agentId, instruction, { ...responseData, processedByAgentId: processedAgentId });
        }
        saveInstruction(agentId, '');

        // SOLUCIÓN CRÍTICA: Si es el CEO (agentId 1), ejecutar workflows automáticamente
        // Esto conecta la respuesta del CEO con el DelegationEngine para ejecutar tareas
        if (agentId === 1 && result.response) {
          console.log('[App] CEO respondió, procesando delegaciones de workflow...');
          try {
            const workflowResult = await processCEOResponseAndExecute(
              result.response,
              instruction,
              { attachments: agentDocuments[agentId] || [] }
              );

            if (workflowResult.delegated) {
              console.log('[App] Workflow ejecutado exitosamente:', workflowResult);
              // Actualizar la respuesta para incluir el resultado del workflow
              const updatedResponse = {
                ...responseData,
                workflowResult,
                workflowExecuted: true
              };
              setInstructionResponse(prev => ({
                ...prev,
                [agentId]: updatedResponse
              }));
            }
          } catch (workflowError) {
            console.error('[App] Error ejecutando workflow:', workflowError);
          }
        }
      } else {
        throw new Error('API error');
      }
    } catch (error) {
      console.log('Using local processing');
      // Fallback response
      const responseData = {
        response: `El agente "${agent.name}" ha recibido la instrucción:\n\n"${instruction}"\n\nHerramientas disponibles para ejecutar:\n${agent.tools.map(t => `• ${t}`).join('\n')}\n\nEl agente procesará esta instrucción utilizando sus capacidades especializadas.`,
        status: 'received',
        timestamp: new Date().toISOString(),
        provider: 'local'
      };
      setInstructionResponse(prev => ({
        ...prev,
        [agentId]: responseData
      }));
      // Save to history and clear textarea
      saveToHistory(agentId, instruction, responseData);
      saveInstruction(agentId, '');
    }

    setProcessingInstruction(null);
  }, [agentInstructions, agentDocuments, saveToHistory, saveInstruction]);

  // Generate Mystery Shopper full report
