    isRunning
    ? 'bg-gray-600 cursor-not-allowed'
    : 'bg-gradient-to-r from-[#C0A062] to-[#A68B4B] hover:from-[#D4B87A] hover:to-[#C0A062] shadow-lg shadow-[#C0A062]/30 text-black'
